                  "properties": {
                    "id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "method": {
                      "type": "string",
                      "enum": [
                        "screwed_butt",
                        "glued_butt",
                        "dowel",
                        "bolted",
                        "unresolved"
                      ]
                    },
                    "first": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "instance_id": {
                          "type": "string",
                          "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                        },
                        "face": {
                          "type": "string",
                          "enum": [
                            "x_min",
                            "x_max",
                            "y_min",
                            "y_max",
                            "z_min",
                            "z_max"
                          ]
                        }
                      },
                      "required": [
                        "instance_id",
                        "face"
                      ]
                    },
                    "second": {
                      "type": "object",
                      "additionalProperties": false,
                      "properties": {
                        "instance_id": {
                          "type": "string",
                          "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                        },
                        "face": {
                          "type": "string",
                          "enum": [
                            "x_min",
                            "x_max",
                            "y_min",
                            "y_max",
                            "z_min",
                            "z_max"
                          ]
                        }
                      },
                      "required": [
                        "instance_id",
                        "face"
                      ]
                    },
                    "reason": {
                      "type": "string",
                      "minLength": 1,
                      "maxLength": 2000
                    }
                  },
                  "required": [
                    "id",
                    "method",
                    "first",
                    "second",
                    "reason"
                  ]
                }
              },
              "remove": {
                "type": "array",
                "maxItems": 1024,
                "items": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                }
