                            "manufacture"
                          ]
                        },
                        "reason": {
                          "type": "string",
                          "minLength": 1,
                          "maxLength": 2000
                        }
                      }
                    },
                    {
                      "type": "object",
                      "additionalProperties": false,
                      "required": [
                        "instance_id",
                        "role",
                        "quantity_policy",
                        "reason"
                      ],
                      "properties": {
                        "instance_id": {
                          "type": "string",
                          "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                        },
                        "role": {
                          "type": "string",
                          "enum": [
                            "existing_part"
                          ]
                        },
                        "quantity_policy": {
                          "type": "string",
                          "enum": [
                            "retain"
                          ]
                        },
                        "reason": {
                          "type": "string",
                          "minLength": 1,
                          "maxLength": 2000
                        }
                      }
                    },
                    {
                      "type": "object",
                      "additionalProperties": false,
                      "required": [
