}$construction_edit_contract$::jsonb;
 policy jsonb:=$construction_edit_policy${"name":"edit_construction_parts","description":"Change only named parts and dependencies of an exact saved construction.","how_to":"Read the exact revision and relevant stable IDs. Send only changed collections with explicit upserts/removals; preserve unrelated parts. Resolve dependent bindings, nodes, joints, materials and roles explicitly. Keep unknown evidence unknown. Use parameter/role commands for those narrower changes. Corrected input gets a new key; exact retry reuses its receipt. Check the saved revision and read_construction_changes before drawing or claiming completion.","schema_version":1,"always_load":false,"preload_phases":[],"active":true}$construction_edit_policy$::jsonb;
 manual text:=$construction_edit_manual$ For changes to existing parts, bindings, formulas, materials or joints, prefer edit_construction_parts: send only the changed posts and preserve the remainder server-side. Use change_construction_parameters for existing input values and change_construction_roles for roles. A full save is for creating a construction or an explicitly complete replacement, not a small correction.$construction_edit_manual$;
 prior shared.ai_prompt_versions; prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}'; key text;
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.save_construction_draft';
 if not found then raise exception 'construction_edit_template_missing'; end if;
 insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind)
  values('bob','tools.edit_construction_parts',policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
 definition:=prior.definition||patch||jsonb_build_object('handler',patch->>'name','required_parameters',patch#>'{parameters,required}','optional_parameters','[]'::jsonb,
  'card_description',policy->>'description','additional_description',policy->>'how_to');
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prompt_uuid,1,'tool_contract',1,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','construction-edits-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('tools.edit_construction_parts',version_uuid);
 for key in select unnest(array['tools.save_construction_draft','tools.change_construction_parameters','bob.tools','bob.workflows']) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=key for update of p;
  if not found then raise exception 'construction_edit_dependency_missing'; end if;
  definition:=prior.definition;
  if key='bob.tools' then
   definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
   definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.edit_construction_parts'));
   definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when s->>'label'='Drawings and CAD' then jsonb_set(s,'{tools}',s->'tools'||jsonb_build_array('edit_construction_parts')) else s end order by n) from jsonb_array_elements(definition->'shelves') with ordinality x(s,n)));
  elsif key='bob.workflows' then
   definition:=jsonb_set(definition,'{workflows}',(select jsonb_agg(case when w->>'name'='workflow_construction_drawing' then w||jsonb_build_object('tools',w->'tools'||jsonb_build_array('edit_construction_parts'),'method',(w->>'method')||manual) else w end order by n) from jsonb_array_elements(definition->'workflows') with ordinality x(w,n)));
  else
   definition:=jsonb_set(definition,'{additional_description}',to_jsonb(coalesce(definition->>'additional_description','')||manual));
   if key='tools.change_construction_parameters' then definition:=jsonb_set(definition,'{description}',to_jsonb(replace(definition->>'description','Use save_construction_draft for topology/material/formula changes.','Use edit_construction_parts for topology/material/formula changes.'))); end if;
  end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','construction-edits-v1'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(key,version_uuid);
 end loop;
 insert into bob.tool_catalog(name,description,how_to,schema_version,always_load,preload_phases,active)
  values(policy->>'name',policy->>'description',policy->>'how_to',1,false,array[]::text[],true);
 perform shared.activate_ai_catalog('bob',activation);
end $construction_edit_publication$;
commit;
